const listReturnableItems = `-- name: ListReturnableItems :many
SELECT si.id,
    si.product_id,
    p.name::text AS product_name,
    p.sell_in_bulk,
    si.quantity,
    si.unit_price::float8 AS unit_price,
    COALESCE(si.discount, 0)::float8 AS discount,
    (si.unit_price * si.quantity - COALESCE(si.discount, 0))::float8 AS net_total,
    COALESCE(r.quantity, 0)::int AS returned_quantity,
    COALESCE(r.total, 0)::float8 AS returned_total
FROM sale_items si
    INNER JOIN products p ON p.id = si.product_id
    LEFT JOIN LATERAL (
        SELECT SUM(ri.quantity) AS quantity,
            SUM(ri.total) AS total
        FROM sale_return_items ri
        WHERE ri.sale_item_id = si.id
    ) r ON TRUE
WHERE si.sale_id = $1
ORDER BY p.name, si.id
`

type ListReturnableItemsRow struct {
	ID               pgtype.UUID `json:"id"`
	ProductID        pgtype.UUID `json:"product_id"`
	ProductName      string      `json:"product_name"`
	SellInBulk       bool        `json:"sell_in_bulk"`
	Quantity         int32       `json:"quantity"`
	UnitPrice        float64     `json:"unit_price"`
	Discount         float64     `json:"discount"`
	NetTotal         float64     `json:"net_total"`
	ReturnedQuantity int32       `json:"returned_quantity"`
	ReturnedTotal    float64     `json:"returned_total"`
}

